  vec2 center=vec2(column*.34+.06*sin(t+row),row*.40+.07*cos(t+column));
  vec2 q=p-center;float d=roundBox(q,vec2(.055,.11),.05);float blur=.035+.06*hash21(vec2(f,seed));float shape=1.-smoothstep(-blur,blur,d);
