vec3 palOriginal(float t){
 int id=int(uPalette+.5);vec3 a=vec3(.5),b=vec3(.5),c=vec3(1.),d=vec3(0.,.33,.67);
 if(id==1){a=vec3(.5,.35,.2);b=vec3(.5,.4,.3);d=vec3(0.,.1,.2);}
 else if(id==2){a=vec3(.2,.5,.6);b=vec3(.3,.4,.4);d=vec3(0.,.25,.55);}
 else if(id==3){c=vec3(1.,1.,.5);d=vec3(.8,.9,.3);}
 else if(id==4){a=vec3(.5,.3,.6);b=vec3(.5,.3,.5);d=vec3(.7,.8,.9);}
 else if(id==5){a=vec3(.2,.4,.2);b=vec3(.3,.4,.3);d=vec3(0.,.2,.1);}
 else if(id==6){a=vec3(.6,.75,.9);b=vec3(.3,.25,.2);d=vec3(0.,.1,.2);}
 else if(id==7){a=vec3(.6,.4,.4);b=vec3(.4,.4,.4);c=vec3(1.,.8,.6);d=vec3(0.,.15,.3);}
 else if(id==8)return vec3(.5+.5*cos(TAU*(t+uHue)));
 return a+b*cos(TAU*(c*(t+uHue)+d));
}

vec3 finishLight(vec3 c){
 c=sourceLight(c);
 float chroma=max(max(c.r,c.g),c.b)-min(min(c.r,c.g),c.b);
 float neutralTint=(1.-smoothstep(.001,.06,chroma))*max(0.,sin(hue*3.14159265))*.8;
 c*=mix(vec3(1),.35+spectral(hue),neutralTint);
 float l=max(max(c.r,c.g),c.b);
 float p=.18*canvas().y+.10*canvas().x+.25*l;
 int mode=int(uRGBAType+.5);
 if(mode>0 || uColorSource>.5){
  vec3 tint;
  if(mode==0)tint=int(uPalette+.5)>=9?palettePreset(int(uPalette+.5),p):palOriginal(p);
  else if(mode==1)tint=hueShift(uRGBA_A.rgb,uHue);
  else{
   float k=clamp(.5+.5*cos(TAU*(p+uHue+(mode==3?time*.055:0.)))+uRGBAMix-.5,0.,1.);
   int op=int(uRGBABlend+.5);
   if(op==1)tint=clamp(uRGBA_A.rgb+uRGBA_B.rgb*k,0.,1.);
   else if(op==2)tint=1.-(1.-uRGBA_A.rgb)*(1.-uRGBA_B.rgb*k);
   else if(op==3)tint=mix(uRGBA_A.rgb,uRGBA_A.rgb*uRGBA_B.rgb,k);
   else tint=mix(uRGBA_A.rgb,uRGBA_B.rgb,k);
  }
  c=max(tint,0.)*l;
 }
 return c*(1.+uHostPulse*.55*(.5+.5*cos(TAU*uHostBeat)));
}
vec3 scene(){
 vec2 p=stage();float t=phase();vec2 q=p+vec2(.10*sin(p.y*3.+t),.12*cos(p.x*2.-t));
 float f=cloud(q*2.,t)+cloud(q*4.1,t)*.20;float ink=smoothstep(.58,.61,f);
 float paper=.82+.16*grain(p,t)*detail;float edge=exp(-abs(f-.595)*90.);
 vec3 c=vec3(mix(.002,paper,ink));c+=vec3(.12)*edge;return finishLight(c);
}

